mapper.select:
select t.*,GROUP_CONCAT(label_id) labels from (select info.id,info.title,info.topic_content,info.status, info.create_time,info.create_by,info.update_time,max(reply.create_time) latestReplyDate, count(reply.id) replyNum,IFNULL(visit.visitNum,0) visitNum from tb_topic_info info left join tb_topic_reply reply on info.id = reply.topic_id left join (select count(id) visitNum,topic_id from tb_topic_visit GROUP BY topic_id) visit on info.id = visit.topic_id GROUP BY info.id) t left join tb_topic_label label on t.id = label.topic_id
and t.title like concat('%',#{title},'%') and t.topic_content like concat('%',#{topicContent},'%') and t.status = #{status}
GROUP BY t.id order by t.update_time desc

mapper.update:
update tb_topic_info
title = #{title}, topic_content = #{topicContent}, remark = #{remark}, status = #{status}, del_flag = #{delFlag}, create_by = #{createBy}, create_time = #{createTime}, update_by = #{updateBy}, update_time = #{updateTime},
where id = #{id}
